def art(kind):
 paths=[]
 for n in range(30):
  if kind=='experience':
   x=100+n*4;y=75+n*4;w=350-n*7;h=360-n*7;r=38
   d=f'M{x+r},{y}H{x+w-r}Q{x+w},{y} {x+w},{y+r}V{y+h-r}Q{x+w},{y+h} {x+w-r},{y+h}H{x+r}Q{x},{y+h} {x},{y+h-r}V{y+r}Q{x},{y} {x+r},{y}Z'
  elif kind=='healthcare':
   r=45+n*4; pts=[]
   for j in range(181):
    a=j/180*math.tau; rad=r*(1+.14*math.cos(4*a));pts.append((280+rad*math.cos(a),260+rad*math.sin(a)))
   d='M'+'L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'Z'
  elif kind=='energy':
   pts=[(j*5,250+(60+n*2)*math.sin(j/110*math.pi*2+n*.07)+n*2-30) for j in range(111)]
   d='M'+'L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)
  elif kind=='intelligence':
   pts=[]
   for j in range(181):
    a=j/180*math.tau;r=75+n*3+18*math.sin(a*3+n*.08);pts.append((280+r*math.cos(a),260+r*math.sin(a)))
   d='M'+'L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'Z'
  else:
   x=280;y=260;r=60+n*4
   d=f'M{x},{y-r}L{x+r},{y}L{x},{y+r}L{x-r},{y}Z'
  paths.append(f'<path d="{d}" style="--delay:{n*.05:.2f}s;opacity:{.18+n*.021:.2f}"/>')
 return '<svg viewBox="0 0 560 520" fill="none" aria-hidden="true">'+''.join(paths)+'</svg>'

